export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:border-primary/45 focus-within:border-ring focus-within:hover:border-ring focus-within:ring-3 focus-within:ring-ring/50 group-invalid:border-destructive group-invalid:ring-3 group-invalid:ring-destructive/20 group-invalid:hover:border-destructive group-invalid:focus-within:border-destructive group-invalid:focus-within:hover:border-destructive group-invalid:focus-within:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-disabled:bg-muted group-disabled:opacity-60 group-disabled:hover:border-input";

export const fieldTriggerStyles =
  "grid size-11 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none transition-[color,background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring disabled:cursor-default disabled:opacity-50";

"use client";

import {
  TextField as AriaTextField,
  type TextFieldProps as AriaTextFieldProps,
  composeRenderProps,
  FieldError,
  Input,
  Label,
  Text,
} from "react-aria-components";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldInputStyles,
  fieldLabelStyles,
} from "./field-styles";

export interface TextFieldProps
  extends Omit<AriaTextFieldProps, "className" | "children"> {
  label?: string;
  description?: string;
  placeholder?: string;
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaTextFieldProps["className"];
  children?: AriaTextFieldProps["children"];
}

export function TextField({
  label,
  description,
  placeholder,
  className,
  children,
  ...props
}: TextFieldProps) {
  return (
    <AriaTextField
      {...props}
      data-slot="text-field"
      className={composeRenderProps(className, (className) =>
        cn("flex w-full flex-col gap-2", className),
      )}
    >
      {children ?? (
        <>
          {label && <TextFieldLabel>{label}</TextFieldLabel>}
          <TextFieldInput placeholder={placeholder} />
          {description && (
            <TextFieldDescription>{description}</TextFieldDescription>
          )}
          <TextFieldError />
        </>
      )}
    </AriaTextField>
  );
}

export function TextFieldLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="text-field-label"
      className={cn(fieldLabelStyles, className)}
    />
  );
}

export function TextFieldInput({
  className,
  ...props
}: React.ComponentProps<typeof Input>) {
  return (
    <Input
      {...props}
      data-slot="text-field-input"
      className={composeRenderProps(className, (className) =>
        cn(fieldInputStyles, "px-3.5", className),
      )}
    />
  );
}

export function TextFieldDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="text-field-description"
      className={cn(fieldDescriptionStyles, className)}
    />
  );
}

export function TextFieldError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="text-field-error"
      className={cn(fieldErrorStyles, className)}
    />
  );
}

"use client";

import { PencilSimpleIcon } from "@phosphor-icons/react";
import { useEffect, useId, useRef, useState } from "react";
import { cn } from "./utils";
import { Button } from "./button";
import { fieldErrorStyles, fieldLabelStyles } from "./field-styles";
import { TextField } from "./text-field";

export interface InlineEditProps {
  label: string;
  value?: string;
  defaultValue?: string;
  onSave?: (value: string) => void | Promise<void>;
  isDisabled?: boolean;
  className?: string;
}

export function InlineEdit({
  label,
  value,
  defaultValue = "",
  onSave,
  isDisabled,
  className,
}: InlineEditProps) {
  const [localValue, setLocalValue] = useState(defaultValue);
  const [draft, setDraft] = useState("");
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState("");
  const errorId = useId();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const hasOpened = useRef(false);
  const savingRef = useRef(false);
  const current = value === undefined ? localValue : value;

  useEffect(() => {
    if (!isEditing && hasOpened.current) triggerRef.current?.focus();
  }, [isEditing]);

  async function save() {
    if (savingRef.current) return;
    if (draft === current) {
      setIsEditing(false);
      return;
    }
    savingRef.current = true;
    setIsSaving(true);
    setError("");
    try {
      await onSave?.(draft);
      if (value === undefined) setLocalValue(draft);
      setIsEditing(false);
    } catch (reason) {
      setError(
        reason instanceof Error && reason.message
          ? reason.message
          : "Could not save. Try again.",
      );
    } finally {
      savingRef.current = false;
      setIsSaving(false);
    }
  }

  return (
    <div className={cn("grid w-full gap-2", className)} data-slot="inline-edit">
      {isEditing ? (
        <div data-slot="inline-edit-editor">
          <div className="flex flex-wrap items-end gap-2">
            <TextField
              label={label}
              value={draft}
              onChange={(next) => {
                setDraft(next);
                setError("");
              }}
              isDisabled={isSaving}
              isInvalid={Boolean(error)}
              aria-describedby={error ? errorId : undefined}
              autoFocus
              className="min-w-0 flex-[1_1_12rem]"
              onKeyDown={(event) => {
                if (isSaving || event.nativeEvent.isComposing) return;
                if (event.key === "Escape") {
                  event.preventDefault();
                  event.stopPropagation();
                  setIsEditing(false);
                } else if (event.key === "Enter") {
                  event.preventDefault();
                  event.stopPropagation();
                  void save();
                }
              }}
            />
            <div className="flex gap-2">
              <Button
                type="button"
                size="sm"
                isDisabled={isSaving}
                onPress={() => void save()}
              >
                {isSaving ? "Saving…" : "Save"}
              </Button>
              <Button
                type="button"
                variant="outline"
                size="sm"
                isDisabled={isSaving}
                onPress={() => setIsEditing(false)}
              >
                Cancel
              </Button>
            </div>
          </div>
          {error && (
            <p
              id={errorId}
              role="alert"
              className={cn("mt-2", fieldErrorStyles)}
            >
              {error}
            </p>
          )}
        </div>
      ) : (
        <>
          <span className={fieldLabelStyles}>{label}</span>
          <div className="flex min-w-0">
            <Button
              ref={triggerRef}
              type="button"
              variant="ghost"
              size="default"
              isDisabled={isDisabled}
              className="-ms-3 min-w-0 max-w-full px-3"
              aria-label={`Edit ${label}: ${current || "Not set"}`}
              onPress={() => {
                setDraft(current);
                setError("");
                hasOpened.current = true;
                setIsEditing(true);
              }}
            >
              <span
                className={cn(
                  "min-w-0 truncate",
                  !current && "text-muted-foreground",
                )}
              >
                {current || "Not set"}
              </span>
              <PencilSimpleIcon
                size={16}
                aria-hidden="true"
                className="shrink-0 text-muted-foreground"
              />
            </Button>
          </div>
        </>
      )}
    </div>
  );
}
